pub(super) fn assert_verified(cwd: &Path, report: &str, exact: bool) {
    let output = run_json(cwd, verify_command(report));
    assert_eq!(output["accepted"], true);
    assert_eq!(output["exact_stage_report_outcome_summary_replayed"], exact);
    assert_summary(&output);
}

fn assert_summary(value: &JsonValue) {
    for (field, expected) in [
        (CHECKED, 1),
        (ACCEPTED, 1),
        (REJECTED, 0),
        (EXACT, 1),
        (COMPLETED, 0),
        (FAILED, 1),
    ] {
        assert_eq!(value[field], expected, "unexpected {field}");
    }
}

fn rejected(cwd: &Path, report: &str) -> JsonValue {
    let output = run(cwd, verify_command(report));
    assert_eq!(output.status.code(), Some(2));
    let json = serde_json::from_slice::<JsonValue>(&output.stdout).unwrap();
    assert_eq!(json["accepted"], false);
    json
}

fn assert_rejected(cwd: &Path, report: &str, message: &str) {
    let output = rejected(cwd, report);
    assert!(output["message"].as_str().unwrap().contains(message));
}

fn verify_command(report: &str) -> [&OsStr; 6] {
    [
        OsStr::new("project"),
        OsStr::new("accept-report"),
        OsStr::new("verify"),
        OsStr::new(report),
        OsStr::new("--format"),
        OsStr::new("json"),
    ]
}

